// src/plugins/workspace/widget-shared.ts
function initials(name) {
  const s = String(name ?? "").replace(/<[^>]*>/g, "").replace(/["“”]/g, "").trim();
  const words = s.split(/[\s._@-]+/).filter((w) => /^[\p{L}]/u.test(w));
  if (!words.length) return "";
  const two2 = words.length > 1 ? words[0][0] + words[1][0] : words[0].slice(0, 2);
  return two2.toLocaleUpperCase("de").replace(/[^A-ZÄÖÜ]/g, "").slice(0, 2);
}

