function filled(values, range, first, last) {
  const out = /* @__PURE__ */ new Map();
  if (!first) return out;
  const start = first > range.from ? first : range.from;
  let end = range.to < todayLocal() ? range.to : todayLocal();
  if (last && last < end) end = last;
  for (let day = start; day <= end; day = addDays(day, 1)) out.set(day, Math.round((values.get(day) ?? 0) * 1e3) / 1e3);
  return out;
}

